def countSmaller(nums, x):
    n = len(nums)
    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[hi]:
            lo = mid + 1
        else:
            hi = mid
    s = lo
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[(s + mid) % n] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo
